#!/usr/bin/env bash
source /home/ubuntu/capstone/assets/solution-lib.bash
# Расширяем data volume базы, гостевое block device и файловую систему без потери данных.
D=/home/ubuntu/capstone/13-resize; ensure_dir "$D"; "${VIRSH[@]}" vol-resize cap-db-data.qcow2 3G --pool capstone-pool >/dev/null; "${VIRSH[@]}" blockresize cap-db --path vdb --size 3G >/dev/null 2>&1 || true; ssh_vm 192.168.151.30 'sudo -n resize2fs /dev/vdb >/dev/null'
cap=$("${VIRSH[@]}" vol-dumpxml --pool capstone-pool cap-db-data.qcow2 | /usr/bin/sed -n "s:.*<capacity unit='bytes'>\([0-9]*\)</capacity>.*:\1:p"); dev=$(ssh_vm 192.168.151.30 'sudo -n blockdev --getsize64 /dev/vdb'); fs=$(ssh_vm 192.168.151.30 "df -B1 --output=size /home/ubuntu/capstone/07-database/data | tail -1 | tr -d ' '"); orders=$(/usr/bin/curl -fsS http://192.168.151.30:54321/orders | /usr/bin/python3 -c 'import json,sys;print(len(json.load(sys.stdin)["orders"]))'); /usr/bin/printf '{"volume_capacity":%s,"guest_device_bytes":%s,"filesystem_bytes":%s,"orders":%s}\n' "$cap" "$dev" "$fs" "$orders" >"$D/evidence.json"; /usr/bin/chown ubuntu:ubuntu "$D/evidence.json"
